from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('prepared.mol',removeHs=False)
p=np.loadtxt('optimized.xyz',skiprows=2,usecols=(1,2,3))
for i in [5,10,15,30]:print('Cu distance',i,np.linalg.norm(p[31]-p[i]))
a,b,c,d=p[[5,10,30,15]];b0=a-b;b1=c-b;b2=d-c;b1/=np.linalg.norm(b1);v=b0-(b0@b1)*b1;w=b2-(b2@b1)*b1
print('dihedral',np.degrees(np.arctan2(np.cross(b1,v)@w,v@w)))
for i in range(m.GetNumAtoms()):m.GetConformer().SetAtomPosition(i,p[i])
Chem.AssignAtomChiralTagsFromStructure(m,replaceExistingTags=True)
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
for i in [1,11,17]:
 a=m.GetAtomWithIdx(i);print(i,a.GetChiralTag(),a.GetProp('_CIPCode') if a.HasProp('_CIPCode') else '-')
# Bond distances compare molecular graph
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();dist=np.linalg.norm(p[i]-p[j]);
 if dist>1.8:print('Long',i,j,b.GetBondType(),dist)
# min nonbonded distances
for i in range(len(p)):
 for j in range(i+1,len(p)):
  if not m.GetBondBetweenAtoms(i,j) and np.linalg.norm(p[i]-p[j])<1.3:print('close',i,j,np.linalg.norm(p[i]-p[j]))
Chem.MolToMolFile(m,'optimized.mol')
